// Builds ONE SQL file that installs the complete Team-Flex database on an EMPTY PostgreSQL database
// (npm run db:install-sql → server/sql/team-flex-install.sql).
//
// It is exactly what `npm run db:init` does on a new database, written out as plain SQL:
//   schema.sql (every table, index, constraint, master data, website content)
//   → every migration in order → the migrations recorded in schema_migrations (same checksums),
// so the app's own `npm run db:init` later sees them as applied and only runs NEW migrations.
//
// Edit schema.sql / migrations, never the generated file.
import crypto from 'node:crypto';
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const dbDir = resolve(root, 'src/database');
const out = resolve(root, 'sql/team-flex-install.sql');

const lf = (s: string) => s.replace(/\r\n/g, '\n');
// same checksum as src/database/migrate.ts
const checksum = (sql: string) => crypto.createHash('sha256').update(lf(sql)).digest('hex');

const schema = lf(readFileSync(resolve(dbDir, 'schema.sql'), 'utf8'));
const migrations = readdirSync(resolve(dbDir, 'migrations'))
  .filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f))
  .sort()
  .map((file) => ({ file, sql: readFileSync(resolve(dbDir, 'migrations', file), 'utf8') }));

const line = '-- ' + '='.repeat(75);
const part = (title: string) => `\n${line}\n-- ${title}\n${line}\n`;

const sql = `${line}
-- TEAM-FLEX — COMPLETE DATABASE INSTALL (one file)
--
-- Creates every table, index and constraint, all master data (permissions, role templates,
-- plans, menus, leave defaults, Help Center articles) and the public website content
-- (Home, Features, Pricing, FAQ, Contact, Privacy, Terms, header & footer).
--
-- Generated by: npm run db:install-sql   (server/scripts/build-install-sql.ts)
-- Source:       src/database/schema.sql + ${migrations.length} migrations (${migrations.at(-1)?.file ?? 'none'})
-- Do not edit this file — edit schema.sql / migrations and generate it again.
--
-- SAFETY
--   * For an EMPTY database only. If Team-Flex tables already exist it stops at once
--     and changes nothing — upgrade an existing database with \`npm run db:init\` instead.
--   * Everything runs in ONE transaction: if any statement fails, nothing is kept.
--   * No users, organizations or business data are created. The first account that signs up
--     becomes the platform admin.
--
-- REQUIREMENTS
--   * PostgreSQL 14 or newer.
--   * Extensions pg_trgm and btree_gist (built in; on managed services such as AWS RDS / Azure /
--     Supabase the database owner can create them).
--
-- RUN
--   createdb team_flex
--   psql -v ON_ERROR_STOP=1 -d team_flex -f team-flex-install.sql
--   (or paste it into pgAdmin / DBeaver query tool on the empty database and run it)
--
-- AFTER
--   Point the server's .env (DB_NAME, …) at this database. \`npm run db:init\` on deploy is still
--   safe: it re-applies schema.sql (idempotent) and runs only migrations newer than these.
${line}

BEGIN;

-- Stop if this is not an empty Team-Flex database (nothing below runs).
DO $install_guard$
BEGIN
  IF to_regclass('public.schema_migrations') IS NOT NULL OR to_regclass('public.users') IS NOT NULL THEN
    RAISE EXCEPTION 'Team-Flex tables already exist in this database. Nothing was changed. Use "npm run db:init" to upgrade an existing database.';
  END IF;
END
$install_guard$;
${part('PART 1 — schema.sql: tables, indexes, constraints, master data, website content')}
${schema.trimEnd()}
${migrations
  .map((m) => `${part(`PART 2 — migration ${m.file}`)}\n${lf(m.sql).trimEnd()}\n`)
  .join('')}
${part('PART 3 — record the migrations as applied (same checksums the app uses)')}
CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(255) PRIMARY KEY, checksum CHAR(64) NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

INSERT INTO schema_migrations (version, checksum) VALUES
${migrations.map((m) => `  ('${m.file}', '${checksum(m.sql)}')`).join(',\n')};

COMMIT;
`;

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, sql);
console.log(`Wrote ${out} (${(sql.length / 1024).toFixed(0)} KB, schema.sql + ${migrations.length} migrations)`);
